      this.reset();
      if (sheetId) void this.reload(sheetId);
    });
  }

  protected open(p: Person): void {
    this.personError.set(null);
    this.patronError.set(null);
    this.editing.set(p.id);
    this.version = p.version;
    this.form.setValue({ name: p.name, grade: this.gradeOf(p), gradeFrom: '', terms: p.terms?.toString() ?? '' });
    this.error.set('');
  }

  /** Take a statement of the person as of the day entered (blank: now), then show them and their
   *  claims as it left them, and clear the day. */
  protected async statement(p: Person, asOf: HTMLInputElement): Promise<void> {
    if (this.stating.has(p.id)) return;
    this.stating.add(p.id);
    this.personError.set(null);
    this.patronError.set(null);
    try {
      this.showTaken(await this.api.statement(p.id, asOf.value || null));
      asOf.value = '';
    } catch {
      this.personError.set({ id: p.id, message: 'The statement could not be taken.' });
    } finally {
      this.stating.delete(p.id);
      reopen: new FormControl('', { nonNullable: true }),
    }),
  });
  protected readonly roleForm = new FormGroup({
    user: new FormControl('', { nonNullable: true }),
    role: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(''));
    this.roleForm.valueChanges.subscribe(() => this.roleError.set(''));
    effect(() => {
      this.session.loads();
      this.session.today(); // what is in force follows the sheet's today
      const sheetId = this.session.sheetId();
      this.clerkLimit.set(null);
      this.cap.set(null);
      this.proofThreshold.set(null);
      this.floor.set(null);
      this.terms.set(null);
      this.gradeTerms.set({});
      this.latePct.set(null);
      this.policyDate.set(null);
      this.periodNumberingFrom.set(null);
      this.graceDays.set(null);
      this.permissions.set({});
      this.roles.set([]);
      if (sheetId) void this.reload(sheetId);
    });
  }

